def find_largest(numbers: list):
    if not numbers:
        raise ValueError("The list cannot be empty.")

    largest = numbers[0]
    for num in numbers[1:]:
        if num > largest:
            largest = num
    return largest

# Example usage:
print(find_largest([3, 14, 7, 2, 19, 5]))  # Output: 19

```
